+                else
+                    videoStreams = mExtractor.getVideoStreams();
+                for (VideoStream video : videoStreams) {
+                    if (video.resolution.equals(mRecovery.desired) && video.getFormat() == mRecovery.format) {
+                        url = video.getUrl();
+                        break;
+                    }
+                }
+                break;
